plugin='''import fs from 'node:fs';import path from 'node:path';
const rows=JSON.parse(fs.readFileSync(new URL('../../meta/pages.json',import.meta.url)));
const aliases={'7.-Flush-policy':'Flush-policy','1.1.-Thread-Safety':'Thread-Safety','3.-Custom-formatting':'Custom-formatting','6.-Asynchronous-logging':'Asynchronous-logging'};
const targets=new Map(rows.map(r=>[r.name.replace(/\\.md$/,''),r.slug]));
export default function(){return(tree,file)=>{const row=rows.find(r=>file.history[0]?.endsWith('/'+r.slug+'.md'));if(!row)return;let active=false,children=[];for(const n of tree.children){if(n.type==='html'&&n.value.includes('<div data-spdlog-source-body=')){active=true;continue;}if(active&&n.type==='html'&&n.value.trim()==='</div>'){active=false;continue;}if(active)children.push(n);}const changes=[];function visit(n){if(n.type==='link'){let name=n.url,hash='';const m=name.match(/^(?:https?:\\/\\/github.com\\/gabime\\/spdlog\\/wiki\\/)?([^/#]+)(#.*)?$/);if(m){name=decodeURIComponent(m[1]).replace(/\\.md$/,'');hash=m[2]??'';name=aliases[name]??name;if(targets.has(name)){const to='/docs/spdlog-trial/v1/en/01-guide/'+targets.get(name)+'/'+hash;changes.push({from:n.url,to});n.url=to;}}}for(const c of n.children??[])visit(c);}for(const n of children)visit(n);const out=path.resolve('meta/ast/'+row.slug+'.json');fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,JSON.stringify({source:row,children,changes},null,2)+'\\n');};}
'''
(app/'src/plugins/remark-spdlog-trial.mjs').write_text(plugin)
